import {comparisonView,detailView,formatMetric} from './evaluation-view.mjs';
import {evaluateAll} from './evaluation-runner.mjs';
import {summarize,exportRows,ROLE_NAMES} from './evaluation.mjs';
import {forecast,FORECAST_IDS,FORECAST_ASSUMPTION,canChangeForecastSelection,applyForecastSelection} from './forecast.mjs';
import {MODELS,DATASETS,METHOD_CARDS} from './catalog.mjs';
import {fieldInfo,validateRows,selectUsableRows,finite} from '../agent/core.mjs';
import {partition,assertDisjoint,assertExperimentWritable} from './engine.mjs';
import * as trainer from './training.mjs';
import {esc,num,panel,chart,table,flow,field,readFile,download,downloadRows} from './ui.mjs';
const experiments=new Map();let modelId='boost',tab='data';
const state=()=>{if(!experiments.has(modelId))experiments.set(modelId,{dataset:MODELS.find(m=>m.id===modelId).dataset,sets:[[],[],[]],all:[],results:[],busy:false,origin:'尚未载入',fit:null,summaries:{},evaluationErrors:{},detailRole:'test',detailWell:null,history:[],ratio:[70,15,15],method:'well-time',status:'等待数据',metrics:null});return experiments.get(modelId);};
export const currentExperiment=()=>({model:MODELS.find(m=>m.id===modelId),...state()});
function files(){return [['all','整体数据'],['0','训练集'],['1','验证集'],['2','测试集']].map(([role,name])=>`<div class="file-box"><label for="upload-${role}">${name}上传</label><small>CSV / JSON · ≤5MB · 字段见右侧</small><input id="upload-${role}" type="file" data-upload="${role}" accept=".csv,.json"></div>`).join('');}
const inlineFields={fraction:['小层比例','0–1'],permeability:['渗透率','毫达西'],thickness:['有效厚度','米'],porosity:['孔隙度','小数0–1'],connectivity:['连通强度','0–1'],measure_code:['措施编码','0酸化 / 1堵水 / 2调参'],incremental:['平均措施增油','标准立方米/日'],distance_m:['井间距离','米'],time_days:['注入后时间','天'],concentration:['示踪剂浓度','源浓度单位']};
function counts(s){const total=s.sets.reduce((n,rs)=>n+rs.length,0),colors=['#a92b38','#b58e51','#4a80ac'];return `<div class="counts">${['训练集','验证集','独立测试集'].map((n,i)=>`<div>${n} · ${total?num(s.sets[i].length/total*100,1):'—'}%<b>${s.sets[i].length} <small>行</small></b></div>`).join('')}</div><div class="split-proportion" aria-label="三组实际样本比例">${s.sets.map((rs,i)=>`<span style="width:${total?rs.length/total*100:0}%;background:${colors[i]}" title="${rs.length}行"></span>`).join('')}</div>`;}
export function renderStudio(){const m=MODELS.find(m=>m.id===modelId),s=state(),ds=DATASETS.find(d=>d.id===s.dataset);return `<div class="model-list">${MODELS.map(x=>`<button data-studio="model" data-id="${x.id}" class="${x.id===modelId?'active':''}">${esc(x.name)}</button>`).join('')}</div><div class="studio"><section class="panel"><div class="panel-head"><div><span class="section-label">MODEL STUDIO / ${esc(m.en)}</span><h2 style="font-size:20px;margin-top:5px">${esc(m.name)}</h2></div><span class="tag ${m.mode==='remote'?'blue':''}">${esc(m.tag)}</span></div><div class="panel-body"><p class="explanation">${esc(m.note)}</p><div class="subtabs">${[['data','01 数据与划分'],['train','02 训练与评价'],['calc','03 计算与导出']].map(([id,n])=>`<button data-studio="tab" data-id="${id}" class="${tab===id?'active':''}">${n}</button>`).join('')}</div>${s.error?`<div class="error-box" role="alert">${esc(s.error)}</div>`:''}${tab==='data'?dataView(m,s,ds):tab==='train'?trainView(m,s):calcView(m,s)}</div></section><aside class="grid">${panel('模型结构',`<div class="architecture">${m.structure.map((n,i)=>`<div class="arch-node"><span>${String(i+1).padStart(2,'0')}</span>${esc(n)}</div>${i<m.structure.length-1?'<div class="arch-arrow">↓</div>':''}`).join('')}</div>`,'<span class="tiny">PPT '+m.page+'</span>')}${panel('数学公式',`<div class="model-formula">${esc(m.formula)}</div>`)}${panel('参数解释与单位',table(m.parameters.map(([p,n,u])=>({p,n,u})),[['p','参数'],['n','解释'],['u','单位 / 默认值']]))}${panel('输入特征字典',table(m.required.map(k=>({k,n:(inlineFields[k]??fieldInfo[k]??[k,'见源数据'])[0],u:(inlineFields[k]??fieldInfo[k]??[k,'见源数据'])[1]})),[['k','字段'],['n','含义'],['u','中文单位']]))}</aside></div><section class="gap">${panel('决策方法与大模型工具链',`<div class="three">${METHOD_CARDS.map(x=>`<article class="method-card"><span class="section-label">PPT ${x.page}</span><h3>${x.name}</h3><code>${esc(x.formula)}</code><div style="margin:12px 0">${flow(x.structure)}</div><p class="tiny">${x.note}</p></article>`).join('')}</div>`)}</section>`;}
function dataView(m,s,ds){return `<div class="toolbar"><label>配套数据 <select id="studio-dataset">${DATASETS.map(d=>`<option value="${d.id}" ${d.id===s.dataset?'selected':''}>${d.name} · ${d.kind==='real'?'实测':'合成'}</option>`).join('')}</select></label><button class="btn primary" data-studio="load" ${s.busy?'disabled':''}>载入并划分</button><a class="btn" href="${ds.csv}" download>↓ 配套CSV</a></div><div class="note ${ds.kind==='real'?'green':''}">${esc(ds.source)} · ${esc(ds.note)}</div><div class="upload-grid">${files()}</div><div class="tool-form">${field('ratio0','训练集 %',s.ratio[0])}${field('ratio1','验证集 %',s.ratio[1])}${field('ratio2','测试集 %',s.ratio[2])}<label>划分方式<select id="split-method">${[['well-time','逐井按时间（推荐）'],['time','全局按时间'],['random','随机划分（事件/样本）'],['well','整井留出']].map(([v,n])=>`<option value="${v}" ${s.method===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="row"><button class="btn" data-studio="split">按当前比例重新划分</button><button class="btn" data-studio="export-split">↓ 导出划分记录</button></div>${counts(s)}<p class="tiny">当前来源：${esc(s.origin)}。时间预测默认逐井按时间划分；随机划分不适用于评估未来预测。每个模型独立保存实验状态，刷新前请导出。</p><div class="schema">${m.required.map(k=>`<code>${esc(k)}</code>`).join('')}</div><p class="tiny">当前数据预览（前3行）</p><pre class="sample">${esc(JSON.stringify((s.all.length?s.all:s.sets.flat()).slice(0,3),null,2))}</pre>`;}
function resultView(s){return detailView(MODELS.find(m=>m.id===modelId),s);}
function trainView(m,s){const losses=[{name:'训练损失',values:s.fit?.history?.map(r=>r.loss)??[],color:'#aa2834'},...(s.fit?.history?.some(r=>finite(r.val_loss))?[{name:'验证损失',values:s.fit.history.map(r=>r.val_loss),color:'#4a7eab',dash:true}]:[])];return `${counts(s)}<div class="note ${m.mode==='remote'?'red':''}">${esc(s.origin)}。${m.mode==='remote'?'XGBoost须连接独立Python服务。':'训练耗时为实际拟合耗时，三组评价另计时；不预填模型表现。'}</div><div class="tool-form">${field('epochs','训练轮次（神经网络）',s.options?.epochs??10)}${field('trees','树数量（树模型）',s.options?.trees??30)}${field('depth','最大树深（树模型）',s.options?.depth??3)}</div><div class="row"><button class="btn primary" data-studio="train" ${s.busy?'disabled':''}>${s.busy?'计算运行中…':'开始训练并评价三组结果'}</button><button class="btn" data-studio="weights" ${!s.fit||s.busy?'disabled':''}>↓ 参数 / 权重</button></div><div class="status" id="studio-status" role="status">${esc(s.status)}${s.fit?' · 拟合'+num(s.fit.duration,3)+'秒':''}${s.evaluationDuration!==undefined?' · 三组评价'+num(s.evaluationDuration,3)+'秒':''}</div><div class="row gap"><button class="btn" data-studio="eval-all" ${!s.fit||s.busy?'disabled':''}>重新评价三组数据</button>${[0,1,2].map((role)=>`<button class="btn" data-studio="eval" data-id="${role}" ${!s.fit||s.busy?'disabled':''}>查看${['训练集','验证集','测试集'][role]}结果</button>`).join('')}</div>${Object.keys(s.evaluationErrors??{}).length?`<div class="note red">${Object.entries(s.evaluationErrors).map(([role,msg])=>esc(ROLE_NAMES[role]+"："+msg)).join("<br>")}</div>`:""}${comparisonView(m,s)}${s.fit?.history?.length?`<div class="gap"><h3>实际训练过程</h3>${chart(losses,{unit:'训练损失值',label:'轮次 / 树迭代'})}</div>`:'<p class="tiny" style="margin-top:16px">数理拟合、规则和无监督隔离树不生成神经网络损失曲线。未提供验证损失时不补画。</p>'}${resultView(s)}`;}
function calcView(m,s){return `<div class="note">输入批次预测与未来趋势分开显示。上传输入按当前模型计算；未来预测固定已有训练参数，并明确外部条件假设。</div><div class="file-box"><label for="calc-file">计算输入 CSV / JSON</label><input type="file" id="calc-file" data-upload="calc" accept=".csv,.json"><small>推理可省略目标标签；仅有输入没有真实值时，保留预测但不计算准确率或误差。</small></div><div class="row gap"><button class="btn" data-studio="calc-test" ${s.busy?'disabled':''}>使用当前测试集</button><button class="btn primary" data-studio="predict" ${!s.fit||s.busy?'disabled':''}>运行模型计算</button></div><div class="status">${esc(s.status)}</div>${forecastView(m,s)}${resultView(s)}`;}
function forecastView(m,s){if(!FORECAST_IDS.has(m.id))return '<div class="note">当前模型输出分类、诊断、剖面比例或空间压力等结果，不适用于日产油/产液时间外推；请查看下方计算结果与分类/回归图表。</div>';const history=s.sets.flat(),wells=[...new Set(history.map(r=>r.well_id))],f=s.forecast,well=f?.rows[0]?.well_id,past=history.filter(r=>r.well_id===well).sort((a,b)=>a.date.localeCompare(b.date)).slice(-30),future=f?.rows??[],dates=[...past.map(r=>r.date),...future.map(r=>r.date)],observed=past.map(r=>r[m.target]);return `<div class="results-heading"><h3>未来生产趋势 · 条件情景预测</h3></div><div class="forecast-config"><div class="forecast-row"><label>预测井<select id="forecast-well" data-studio-change="forecast-well" ${s.busy?'disabled':''}>${wells.map(w=>`<option ${w===(s.forecastWell??wells[0])?'selected':''}>${esc(w)}</option>`).join('')}</select></label><label>未来天数<input id="forecast-days" type="number" min="1" max="60" value="${s.forecastDays??7}" ${s.busy?'disabled':''}></label><button class="btn primary" data-studio="forecast" ${!s.fit||s.busy?'disabled':''}>生成未来预测</button><button class="btn" data-studio="forecast-export" ${!future.length?'disabled':''}>↓ 未来预测CSV</button></div><p class="forecast-hint" style="margin-top:12px">${FORECAST_ASSUMPTION} 起算点为所选井全部已观测历史的末日；不会用未来真实值或重新拟合模型。</p></div>${f?`<div class="result-kpis"><div><span>首个未来预测 / ${esc(m.unit)}</span><b>${num(future[0]?.prediction)}</b></div><div><span>末日预测 / ${esc(m.unit)}</span><b>${num(future.at(-1)?.prediction)}</b></div><div><span>预测期累计 / 标准立方米</span><b>${num(future.reduce((a,r)=>a+r.prediction,0),1)}</b></div><div><span>实际预测耗时 / 秒</span><b>${num(f.duration,3)}</b></div></div>${chart([{name:'已观测历史',values:[...observed,...future.map(()=>null)],labels:dates,color:'#b58e51'},{name:'未来条件预测',values:[...past.map((_,i)=>i===past.length-1?observed[i]:null),...future.map(r=>r.prediction)],labels:dates,color:'#a92b38',dash:true},...(future.some(r=>r.lower!==null)?[{name:'验证残差下参考线',values:[...past.map(()=>null),...future.map(r=>r.lower)],color:'#8297ab',dash:true},{name:'验证残差上参考线',values:[...past.map(()=>null),...future.map(r=>r.upper)],color:'#a6b3bd',dash:true}]:[])],{unit:m.unit,label:'实际日期；历史实线 / 未来虚线'})}<div class="note">${esc(f.referenceBand)}。递归多步预测的误差会累积；参考线不保证未来覆盖率。${f.warnings.length?'<br>'+esc(f.warnings.join('；')):''}</div>${table(future,[['date','预测日期'],['horizon','未来第几天'],['prediction','模型预测'],['lower','残差下参考'],['upper','残差上参考'],['unit','中文单位']],30)}`:''}`;}
function invalidate(s){s.fit?.network?.dispose?.();s.fit=null;s.results=[];s.summaries={};s.evaluationErrors={};s.evaluationDuration=undefined;s.forecast=null;s.resultSource=null;s.metrics=null;s.status='数据已变更，请重新训练';}
function checkRows(m,rows){validateRows(rows,m.required);if(rows.length<3)throw Error('至少需要3条记录');}
export async function studioAction(action,id,{render,remote,notify}){const m=MODELS.find(m=>m.id===modelId),s=state();if(['load','split','train','eval-all','forecast','predict'].includes(action)&&s.busy){notify('模型正在训练，请等待完成后再修改数据');return;}s.error='';try{if(['load','split','train','eval-all','forecast','predict'].includes(action))assertExperimentWritable(s);if(action==='model'){modelId=id;tab='data';render();return;}if(action==='tab'){tab=id;render();return;}if(action==='load'){const ds=DATASETS.find(d=>d.id===document.getElementById('studio-dataset').value);s.dataset=ds.id;const r=await fetch(ds.path);if(!r.ok)throw Error('数据载入失败');const rows=await r.json();checkRows(m,rows);invalidate(s);s.all=rows;s.origin=ds.name+' · '+ds.source;s.method=['event3w','esp','effect'].includes(m.id)?'random':['tracer','horner'].includes(m.id)?'well-time':'well-time';s.sets=partition(rows,s.ratio,s.method);s.status='已载入'+rows.length+'行';}
 else if(action==='split'){s.ratio=[0,1,2].map(i=>Number(document.getElementById('ratio'+i).value));s.method=document.getElementById('split-method').value;if(!s.all.length)throw Error('请先载入或上传整体数据');const out=partition(s.all,s.ratio,s.method);invalidate(s);s.sets=out;}
 else if(action==='train'){if(s.busy)return;assertDisjoint(s.sets);checkRows(m,s.sets[0]);if(!s.sets[1].length||!s.sets[2].length)throw Error('请补充独立验证集与测试集');s.options={epochs:Math.max(1,Math.min(100,Number(document.getElementById('epochs').value)||10)),trees:Math.max(1,Math.min(100,Number(document.getElementById('trees').value)||30)),depth:Math.max(1,Math.min(5,Number(document.getElementById('depth').value)||3))};invalidate(s);s.busy=true;s.status='训练中…';render();await new Promise(r=>setTimeout(r,30));s.fit=await trainer.train(m,s.sets[0],s.sets[1],s.options,(p,logs)=>{s.status='训练进度 '+Math.round(p*100)+'% · loss='+num(logs?.loss,5);const el=document.getElementById('studio-status');if(el)el.textContent=s.status;},remote);await evaluateExperiment(m,s,remote);s.status='训练完成 · '+s.fit.trainedRows+'条拟合样本；三组结果已分别保留';s.busy=false;notify('训练、验证、测试三组评价完成');}
 else if(action==='eval-all'){if(!s.fit)throw Error('请先训练');s.busy=true;s.status='重新计算三组结果…';render();await evaluateExperiment(m,s,remote);s.busy=false;s.status='三组结果已更新';}
 else if(action==='eval'){if(!s.fit)throw Error('请先训练');const role=['train','validation','test'][Number(id)];if(!s.summaries?.[role])throw Error(s.evaluationErrors?.[role]??'该组还没有可用结果，请重新评价三组');s.resultSource=null;s.detailRole=role;s.detailWell=null;s.results=s.summaries[role].rows;s.metrics=s.summaries[role].metrics;s.evalRole=ROLE_NAMES[role]+'指标';s.status='查看'+ROLE_NAMES[role]+'结果';}
 else if(action==='calc-test'){s.calc=s.sets[2];s.status='计算输入采用当前测试集'+s.calc.length+'行';}
 else if(action==='predict'){if(!s.fit)throw Error('请先训练');if(!s.calc?.length)throw Error('请上传计算输入或选择测试集');s.busy=true;s.status='正在计算输入预测…';render();s.results=(await trainer.predict(m,s.fit,s.calc,[...s.sets[0],...s.sets[1]],remote)).map(r=>({...r,actual:r.actual??r[m.target]}));s.resultSource='calc';s.detailWell=null;s.busy=false;s.status='计算完成 · '+s.results.length+'条';}
 else if(action==='results'){const rows=s.resultSource==='calc'?s.results:s.summaries?.[s.detailRole??'test']?.rows??s.results;downloadRows(m.id+'-results.csv',exportRows({[s.resultSource==='calc'?'计算输入':s.detailRole??'test']:{rows,kind:summarize(m,rows).kind}},s.origin));return;}
 else if(action==='evaluation-export'){if(!Object.keys(s.summaries??{}).length)throw Error('请先完成模型评价');download(m.id+'-evaluation.json',JSON.stringify({model:m.id,source:s.origin,ratios:s.ratio,fitDuration:s.fit.duration,evaluationDuration:s.evaluationDuration,summaries:s.summaries,errors:s.evaluationErrors},null,2),'application/json');return;}
 else if(action==='forecast'){if(!s.fit)throw Error('请先训练');s.forecastDays=Number(document.getElementById('forecast-days').value);s.forecastWell=document.getElementById('forecast-well').value;s.busy=true;s.status='正在计算未来条件预测…';render();s.forecast=await forecast(m,s.fit,s.sets.flat(),{days:s.forecastDays,well:s.forecastWell,remote,residuals:s.summaries?.validation?.evaluated?.map(r=>r.error)??[]});s.busy=false;s.status='请求未来'+s.forecastDays+'天，已生成'+s.forecast.rows.length+'条条件预测';}
 else if(action==='forecast-export'){if(!s.forecast?.rows.length)throw Error('请先生成未来预测');downloadRows(m.id+'-future-scenario.csv',s.forecast.rows.map(r=>({...r,source:s.origin})));return;}
 else if(action==='weights'){if(!s.fit)throw Error('尚未训练');download(m.id+'-model.json',JSON.stringify({model:m.id,source:s.origin,ratio:s.ratio,...await trainer.serialize(m,s.fit)},null,2),'application/json');return;}
 else if(action==='export-split'){download(m.id+'-splits.json',JSON.stringify({model:m.id,source:s.origin,method:s.method,ratios:s.ratio,train:s.sets[0],validation:s.sets[1],test:s.sets[2]},null,2),'application/json');return;}
 }catch(e){s.error=e.message;s.busy=false;notify(e.message);}render();}
export async function studioUpload(role,file,{render,notify}){const m=MODELS.find(m=>m.id===modelId),s=state();try{assertExperimentWritable(s);const rows=await readFile(file);assertExperimentWritable(s);if(role==='calc'){s.calc=rows;s.status='已载入计算输入'+rows.length+'行';}else{checkRows(m,rows);if(role==='all'){const sets=partition(rows,s.ratio,s.method);invalidate(s);s.all=rows;s.sets=sets;s.origin='用户上传：'+file.name;}else{const sets=s.sets.map((r,i)=>i===Number(role)?rows:r);assertDisjoint(sets);invalidate(s);s.sets=sets;s.all=[];s.origin='用户分别上传（请自行核实现场来源与标签）';}}s.error='';notify('数据载入完成');}catch(e){s.error=e.message;notify(e.message);}render();}

async function evaluateExperiment(m,s,remote){const result=await evaluateAll(m,s.fit,s.sets,remote,{progress:status=>{s.status=status;const el=document.getElementById('studio-status');if(el)el.textContent=status;}});s.summaries=result.summaries;s.evaluationErrors=result.errors;s.evaluationDuration=result.duration;s.detailRole='test';s.resultSource=null;s.results=result.summaries.test?.rows??[];s.metrics=result.summaries.test?.metrics??null;s.evalRole='独立测试指标';}
export function studioSelection(name,value,{render}){const s=state();if(name==='forecast-well'&&!canChangeForecastSelection(s))return;if(name==='role'){s.detailRole=value;s.detailWell=null;s.resultSource=null;s.results=s.summaries?.[value]?.rows??[];s.metrics=s.summaries?.[value]?.metrics??null;s.evalRole=ROLE_NAMES[value]+'指标';}else if(name==='well')s.detailWell=value;else if(name==='forecast-well'){applyForecastSelection(s,value);}render();}
